/**
 * Maintenance tool: turn the wiki-derived research dump into the compact version
 * table the validator and the reference docs read.
 *
 * Usage:
 *   node scripts/tools/build-versions.mjs <research/pack-formats.json> <reference/data/versions.json>
 *
 * Run this when Minecraft ships a release. The generated file is what ships; this
 * script exists so the numbers are transcribed by machine and not by hand.
 */

import { readFileSync, writeFileSync } from "node:fs";

const [, , inputPath, outputPath] = process.argv;
if (inputPath === undefined || outputPath === undefined) {
	process.stderr.write("usage: node build-versions.mjs <research/pack-formats.json> <reference/data/versions.json>\n");
	process.exit(2);
}

const research = JSON.parse(readFileSync(inputPath, "utf8"));

/** Split a `pack_format` value and its display string into major/minor integers. */
function splitFormat(value, display) {
	const text = display ?? String(value);
	const [majorText, minorText] = String(text).split(".");
	const major = Math.floor(Number(value));
	const minor = minorText === undefined ? 0 : Number(minorText);
	return { major, minor };
}

const formatGroups = research.releases.map((release) => {
	const { major, minor } = splitFormat(release.pack_format, release.pack_format_display);
	const list = release.versions_list ?? [];
	return {
		pack_format: major,
		minor,
		display: release.pack_format_display ?? String(release.pack_format),
		from: list[0] ?? "",
		to: list.at(-1) ?? "",
		versions: release.versions,
		data_version_first: release.data_version,
		data_version_last: release.data_version_last ?? release.data_version,
		notes: release.notes
	};
});

const versionToFormat = {};
const versionToDataVersion = {};
for (const row of research.releases_by_version ?? []) {
	versionToFormat[row.version] = Math.floor(Number(row.pack_format));
	versionToDataVersion[row.version] = row.data_version;
}

const knownFormats = [...new Set(formatGroups.map((group) => group.pack_format))].sort((a, b) => a - b);
const latestSnapshot = research.latest_snapshot;
if (latestSnapshot !== undefined) {
	const { major } = splitFormat(latestSnapshot.pack_format, latestSnapshot.pack_format_display);
	if (!knownFormats.includes(major)) knownFormats.push(major);
}
knownFormats.sort((a, b) => a - b);

const era = {
	note: "Java picks its version-field format at game version 1.21.8 / data pack format 81. A pack that targets only 1.21.8 or earlier must use pack_format; a pack that targets only 1.21.9 or later must use min_format and max_format; a pack that spans both must supply all four fields.",
	legacyThroughVersion: "1.21.8",
	legacyMax: 81,
	modernFromVersion: "1.21.9",
	modernMin: 82
};

const output = {
	$comment: "Generated by scripts/tools/build-versions.mjs from the wiki-derived research dump. This is the single source of truth for pack format numbers; the validator and the reference docs both read it. Do not hand-edit.",
	generatedFrom: research.generatedAt,
	gameVersioningNote: "From 1.21.9 (25w31a) a data pack format number has a major and a minor part (88.0, 94.1, 101.1, 107.1, 121.0). In JSON the number is the major version; write the pair as an array, e.g. min_format: [88, 0].",
	latest_release: research.latest_release,
	latest_snapshot: latestSnapshot,
	era,
	knownFormats,
	formatGroups,
	versionToFormat,
	versionToDataVersion,
	aprilFools: research.april_fools ?? [],
	sources: research.sources ?? [],
	uncertainties: research.uncertainties ?? []
};

writeFileSync(outputPath, `${JSON.stringify(output, null, 2)}\n`, "utf8");
process.stdout.write(`wrote ${outputPath}: ${formatGroups.length} format groups, ${Object.keys(versionToFormat).length} versions, formats ${knownFormats[0]}–${knownFormats.at(-1)}\n`);
